import com.google.gson.*;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class CounterScalingTest {
    static final UUID A=DiscardAbilityCountTest.A,B=DiscardAbilityCountTest.B;
    static void check(boolean b,String why){DiscardAbilityCountTest.check(b,why);}
    static void reject(Runnable r){DiscardAbilityCountTest.reject(r);}
    static void atomic(ServerMatch m,Runnable r){GeneratedRuleBatch44Test.assertRejectedAtomic(m,r);}
    static final String GLOBAL=DiscardAbilityCountTest.GLOBAL;
    static final String SPIN="{\"type\":\"damage_counter\",\"target\":\"ALL_OPPONENT_POKEMON\",\"amount\":4}";
    static final String END="{\"type\":\"damage_counter\",\"target\":\"SELECT_OPPONENT_POKEMON\",\"target_count\":2,\"counter_multiplier\":4}";
    static EffectDefinition effect(String json){return DiscardAbilityCountTest.effect(json);}
    static AbilityDefinition passive(String id,String json){return DiscardAbilityCountTest.passive(id,json);}
    static AbilityDefinition hide(){return BundledCombatData.load().pokemon("me5_en_006").orElseThrow().abilities().getFirst();}
    static AttackDefinition spin(){return attack("spin",6,SPIN);}
    static AttackDefinition end(){return attack("end",13,END);}
    static AttackDefinition attack(String id,int threshold,String text){return BundledCombatData.attack(JsonParser.parseString("{\"id\":\""+id+"\",\"nameZh\":\"指示物测试\",\"energyCost\":{},\"baseDamage\":0,\"damageType\":\"PSYCHIC\",\"effectSupport\":\"SUPPORTED\",\"triggers\":[{\"trigger\":\"AFTER_ATTACK\",\"effects\":[{\"type\":\"conditional\",\"conditions\":[{\"type\":\"DISCARD_COUNT\",\"target\":\"SELF\",\"ability_id\":\"hide-n-sneak\",\"value\":"+threshold+",\"comparison\":\">=\"}],\"effects\":["+text+"]}]}]}").getAsJsonObject(),EffectRegistry.standard());}
    static CardDefinition card(String id,CardCategory category,TrainerCategory trainer,boolean basic){return new CardDefinition(id,id,category,trainer,"J",Set.of("international"),basic,id.equals("energy"),60,Map.of(),EffectSupport.SUPPORTED,null);}
    static PokemonProfile profile(String from,List<AbilityDefinition> abilities){return new PokemonProfile(1000,0,from,null,0,null,0,1,List.of(spin(),end(),CopyAttackTest.copier()),abilities,EnergyType.PSYCHIC);}
    static ServerMatch game(){return game(null,null,null);}
    static ServerMatch game(CardDefinition real,PokemonProfile actual,AbilityDefinition actualHide){
        String actor=real==null?"actor":real.id();String opener=actual!=null&&actual.evolvesFromDefinitionId()!=null?actual.evolvesFromDefinitionId():actor;var definitions=new ArrayList<CardDefinition>();var profiles=new LinkedHashMap<String,PokemonProfile>();
        var draw=new AbilityDefinition("draw","测试抽牌",new AbilityEffect(AbilityEffect.Opcode.DRAW,1),EffectSupport.SUPPORTED,null);
        var hidden=actualHide==null?hide():actualHide;
        profiles.put(actor,actual==null?profile(null,List.of(draw)):actual);profiles.put("base",profile(null,List.of(draw)));
        profiles.put("hide-a",profile(null,List.of(hidden)));profiles.put("hide-b",profile("base",List.of(hidden)));
        profiles.put("decoy",profile(null,List.of(passive("different-id","{\"type\":\"passive_effect_guard\",\"target\":\"SELF\",\"source\":\"ABILITY\",\"from\":\"OPPONENT\",\"scope\":\"DAMAGE_AND_EFFECTS\"}"))));
        profiles.put("global",profile("base",List.of(passive("garbotoxin",GLOBAL))));
        if(!opener.equals(actor))profiles.put(opener,BundledCombatData.load().pokemon(opener).orElseThrow());
        for(var e:profiles.entrySet())definitions.add(real!=null&&e.getKey().equals(actor)?real:e.getKey().equals(opener)&&!opener.equals(actor)?BundledRules.loadCardDefinitions().find(opener).orElseThrow():card(e.getKey(),CardCategory.POKEMON,TrainerCategory.NONE,e.getValue().evolvesFromDefinitionId()==null));
        var trainers=new LinkedHashMap<String,TrainerProfile>();
        trainers.put("tool",BundledCombatData.trainer(JsonParser.parseString("{\"trainerCategory\":\"TOOL\",\"effects\":[{\"type\":\"retreat_cost_modifier\",\"target\":\"SELF\",\"amount\":-1}]}").getAsJsonObject(),EffectRegistry.standard()));
        trainers.put("field",new TrainerProfile(TrainerCategory.STADIUM,new TrainerEffect(TrainerEffect.Opcode.PASSIVE_STADIUM,0,0),new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.PASSIVE,List.of(),List.of(effect("{\"type\":\"suppress_abilities\",\"target\":\"SELF\",\"scope\":\"ALL_IN_PLAY\"}")))))));
        trainers.put("clear",new TrainerProfile(TrainerCategory.STADIUM,new TrainerEffect(TrainerEffect.Opcode.STADIUM_BASIC_RETREAT_REDUCTION,1,0)));
        for(String id:trainers.keySet())definitions.add(card(id,CardCategory.TRAINER,id.equals("tool")?TrainerCategory.TOOL:TrainerCategory.STADIUM,false));definitions.add(card("energy",CardCategory.ENERGY,TrainerCategory.NONE,false));
        var catalog=new CombatCatalog(profiles,Map.of("energy",EnergyType.PSYCHIC),trainers);var decks=new ArrayList<List<CardInstance>>();
        for(UUID player:List.of(A,B)){var list=new ArrayList<CardInstance>();for(int i=0;i<60;i++){String id=i<14?(!opener.equals(actor)&&i%2==0?opener:actor):i<20?"base":i<30?"hide-a":i<40?"hide-b":i<42?"decoy":i<46?"global":i<50?"tool":i<53?"field":i<56?"clear":"energy";list.add(new CardInstance(new UUID(player.getLeastSignificantBits(),i+1),player,id));}decks.add(list);}
        for(int seed=0;seed<1000;seed++){
            var m=new ServerMatch(A,B,decks.get(0),decks.get(1),GeneratedRuleBatch8Test.RULES,new CardDatabase(definitions),catalog,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);
            if(m.privateView(A).hand().stream().noneMatch(c->c.definitionId().equals(opener))||m.privateView(A).hand().stream().noneMatch(c->c.definitionId().equals("base"))||m.privateView(B).hand().stream().filter(c->c.definitionId().equals("base")).count()<2)continue;
            for(UUID p:List.of(A,B)){m.chooseOpeningActive(p,hand(m,p,p.equals(A)?opener:"base").instanceId());m.placeOpeningBench(p,hand(m,p,"base").instanceId());m.startAfterOpening(p);}OpeningTestSupport.complete(m,A,B,0);m.endTurn(A);m.endTurn(B);if(!opener.equals(actor))m.evolve(A,active(m,A),get(m,A,actor).instanceId());return m;
        }throw new AssertionError("No discard fixture");
    }
    static CardInstance hand(ServerMatch m,UUID p,String id){return m.privateView(p).hand().stream().filter(c->c.definitionId().equals(id)).findFirst().orElseThrow();}
    static CardInstance get(ServerMatch m,UUID p,String id){var found=m.privateView(p).hand().stream().filter(c->c.definitionId().equals(id)).findFirst();if(found.isPresent())return found.get();check(m.currentPlayer().equals(p),"Only current owner searches fixture deck");var c=m.privateView(p).deck().stream().filter(v->v.definitionId().equals(id)).findFirst().orElseThrow();m.searchOwnDeckToHandByEffect(p,List.of(c.instanceId()));return c;}
    static void discard(ServerMatch m,String id,int n){for(int i=0;i<n;i++)m.discardHandCardsByEffect(A,A,List.of(get(m,A,id).instanceId()));}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static UUID source(ServerMatch m){UUID id=m.benchPokemonView(A).getFirst().pokemonId();m.evolve(A,id,get(m,A,"global").instanceId());return id;}
    static void tool(ServerMatch m,UUID host){m.playTrainer(A,get(m,A,"tool").instanceId(),host);}
    static int count(ServerMatch m,UUID owner,String ability){try{var method=ServerMatch.class.getDeclaredMethod("discardCount",UUID.class,Map.class);method.setAccessible(true);return (int)method.invoke(m,owner,ability==null?Map.of():Map.of("ability_id",ability));}catch(ReflectiveOperationException e){throw new AssertionError(e);}}

    static void fill(ServerMatch m,int n){discard(m,"hide-a",Math.min(n,7));discard(m,"hide-b",Math.max(0,n-7));}
    static UUID bench(ServerMatch m){return m.benchPokemonView(B).getFirst().pokemonId();}
    static void choose(ServerMatch m,UUID target){var p=m.effectPokemonPrompt(A);m.chooseEffectPokemon(A,p.resolutionId(),p.step(),target);}
    static int damage(ServerMatch m,UUID id){return m.activePokemonView(B).pokemonId().equals(id)?m.activePokemonView(B).damage():m.benchPokemonView(B).stream().filter(v->v.pokemonId().equals(id)).findFirst().orElseThrow().damage();}
    public static void main(String[] args){group();multiple();oneTarget();guards();abilityGuard();suppression();copies();knockouts();schema();System.out.println("CounterScalingTest passed:6/13 thresholds, unconditional whole-opponent group, deferred distinct2 targets or available1, each current counter total quadrupled including0 and>60 added, guards, live Ability removal, actual copy owner, atomic authority/replay, simultaneous KO and strict multiplier attack-only schema and preserved automatic whole-field counters");}
    static void group(){for(int n:List.of(5,6,7)){var m=game();fill(m,n);UUID b=bench(m);m.placeDamageCountersByEffect(A,B,b,1);m.attack(A,"spin");int added=n>=6?40:0;check(m.activePokemonView(B).damage()==added&&damage(m,b)==10+added&&m.activePokemonView(A).damage()==0&&m.benchPokemonView(A).getFirst().damage()==0&&m.lastAttack().finalDamage()==0&&!m.hasPendingPokemonSelection()&&m.currentPlayer().equals(B),"Group/threshold treated as damage, choice or wrong side");}}
    static void multiple(){for(int n:List.of(12,13,14)){var m=game();fill(m,n);UUID a=active(m,B),b=bench(m);if(n!=14)m.placeDamageCountersByEffect(A,B,a,3);m.placeDamageCountersByEffect(A,B,b,2);m.attack(A,"end");if(n==12){check(!m.hasPendingPokemonSelection()&&damage(m,a)==30&&damage(m,b)==20,"Unmet threshold still asked/placed");continue;}var p=m.effectPokemonPrompt(A);atomic(m,()->m.chooseEffectPokemon(B,p.resolutionId(),p.step(),a));atomic(m,()->m.chooseEffectPokemon(A,p.resolutionId(),p.step(),active(m,A)));choose(m,a);check(damage(m,a)==(n==14?0:30)&&damage(m,b)==20,"Placement happened before all targets chosen");atomic(m,()->m.chooseEffectPokemon(A,p.resolutionId(),p.step(),a));choose(m,b);check(damage(m,a)==(n==14?0:120)&&damage(m,b)==80&&m.lastAttack().finalDamage()==0&&m.currentPlayer().equals(B),"Quadruple did not use each independent original total");atomic(m,()->m.chooseEffectPokemon(A,p.resolutionId(),p.step(),b));}}
    static void oneTarget(){var m=game();fill(m,13);m.movePokemonByEffect(A,B,bench(m),LeavePlayDestination.HAND);UUID a=active(m,B);m.placeDamageCountersByEffect(A,B,a,2);m.attack(A,"end");check(m.effectPokemonPrompt(A).targets().size()==1,"Only target not issued");choose(m,a);check(damage(m,a)==80&&m.currentPlayer().equals(B),"Insufficient2 targets did not use available1");}
    static void guard(ServerMatch m,String scope){m.executeEffectProgramByRule(A,active(m,A),new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.ON_CARD_PLAYED,List.of(),List.of(effect(EffectOriginProtectionTest.shield("ATTACK",scope,"OPPONENT_ACTIVE","LEAVES_PLAY")))))),EffectTrigger.ON_CARD_PLAYED);}
    static void guards(){for(boolean scale:List.of(false,true))for(String scope:List.of("DAMAGE_ONLY","EFFECTS_ONLY")){var m=game();fill(m,scale?13:6);UUID a=active(m,B),b=bench(m);m.placeDamageCountersByEffect(A,B,a,2);m.placeDamageCountersByEffect(A,B,b,1);guard(m,scope);m.attack(A,scale?"end":"spin");if(scale){choose(m,a);choose(m,b);}check(damage(m,a)==(scope.equals("EFFECTS_ONLY")?20:scale?80:60)&&damage(m,b)==(scale?40:50),"Counter guard incorrectly used attack-damage prevention "+scope);}}
    static void abilityGuard(){var m=game();m.endTurn(A);m.playBasicPokemonToBench(B,get(m,B,"hide-a").instanceId());m.endTurn(B);UUID protectedId=m.benchPokemonView(B).stream().filter(v->v.topCardId().equals("hide-a")).findFirst().orElseThrow().pokemonId();fill(m,6);m.attack(A,"spin");check(damage(m,protectedId)==0&&m.activePokemonView(B).damage()==40,"Hide n Sneak did not block counter attack effect independently");}
    static void suppression(){for(boolean field:List.of(false,true)){var m=game();fill(m,13);tool(m,source(m));if(field)m.playTrainer(A,get(m,A,"field").instanceId(),null);UUID a=active(m,B),b=bench(m);m.placeDamageCountersByEffect(A,B,a,2);m.placeDamageCountersByEffect(A,B,b,1);m.attack(A,"end");check(m.hasPendingPokemonSelection()==field,"Live discard Ability removal did not gate targets");if(field){choose(m,a);choose(m,b);}check(damage(m,a)==(field?80:20),"Wrong live Ability threshold");}}
    static void copies(){var m=game();fill(m,13);m.attachEnergy(A,get(m,A,"energy").instanceId(),active(m,A));UUID a=active(m,B),b=bench(m);m.placeDamageCountersByEffect(A,B,a,1);m.placeDamageCountersByEffect(A,B,b,2);var o=m.copyAttackOptions(A,"copy").stream().filter(v->v.attackId().equals("end")).findFirst().orElseThrow();m.copyAttackWithEnergyDiscards(A,"copy",o.pokemonId(),o.entrySequence(),o.attackId(),List.of(),List.of());choose(m,a);choose(m,b);check(damage(m,a)==40&&damage(m,b)==80&&count(m,B,"hide-n-sneak")==0,"Copied source used provider discard or targets");}
    static void knockouts(){for(boolean group:List.of(false,true)){var m=game();m.endTurn(A);m.playBasicPokemonToBench(B,get(m,B,"base").instanceId());m.endTurn(B);fill(m,group?6:13);UUID a=active(m,B),b=bench(m);int counters=group?98:40;for(UUID id:List.of(a,b)){int left=counters;while(left>0){int n=Math.min(60,left);m.placeDamageCountersByEffect(A,B,id,n);left-=n;}}m.attack(A,group?"spin":"end");if(!group){choose(m,a);check(m.hasPendingPokemonSelection(),"First choice prematurely reached KO");choose(m,b);}check(m.phase()==MatchPhase.PRIZE_SELECTION&&m.lastAttack().finalDamage()==0,"Counter KO not deferred as attack-effect KO");m.takePrizeAt(A,0);m.takePrizeAt(A,0);m.chooseReplacement(B,m.benchPokemonView(B).getFirst().pokemonId());check(m.privateView(A).prizes().size()==4&&m.currentPlayer().equals(B),"Simultaneous two-target KO awarded wrong prizes or ended early");}}
    static void schema(){TriggeredAbilityRules.validate(CheckupTriggeredAbilityTest.ability("group",false,SPIN));reject(()->TriggeredAbilityRules.validate(CheckupTriggeredAbilityTest.ability("multiply",false,END)));AttackProgramRules.validate(spin());AttackProgramRules.validate(end());for(String text:List.of(END.replace(":4",":1"),END.replace("SELECT_OPPONENT_POKEMON","SELF"),END.replace(":2",":1"),END.replace("counter_multiplier","remaining_hp"),SPIN.replace("amount","counter_multiplier")))reject(()->effect(text));for(String text:List.of(SPIN,END)){var e=effect(text);reject(()->TrainerProgramRules.validate(new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.ON_CARD_PLAYED,List.of(),List.of(e))))));reject(()->ResumableProgramRules.validate(new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.BEFORE_ATTACK,List.of(),List.of(e)))),true,EffectTrigger.BEFORE_ATTACK));var m=game();atomic(m,()->m.executeEffectProgramByRule(A,active(m,A),new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.ON_CARD_PLAYED,List.of(),List.of(e)))),EffectTrigger.ON_CARD_PLAYED));}}
}
